// Gringotts — your own copy (v7.40). All the app's code is the shared Gringotts library ("G"). This file hands the
// library this copy's own settings, memory, lock and timers on every run, so nothing of yours is ever mixed with
// anyone else's, and nobody else can see it. Please don't edit: updates replace this file.

function host_() {
  return { props: PropertiesService.getScriptProperties(), cache: CacheService.getScriptCache(), lock: LockService.getScriptLock(), app: ScriptApp };
}
function run_(name, args) { G.useHost(host_()); return G[name].apply(null, args || []); }

// the web app (the page and the phone's SMS) and the page's calls
function doGet(e) { return run_('doGet', [e]); }
function doPost(e) { return run_('doPost', [e]); }
function api(name, args) { return run_('api', [name, args]); }
function timed(name, args, once) { return run_('timed', [name, args, once]); }   // the same door, timed for the Speed log (v7.42.3); once: a save sent again isn't made twice (v7.43.2, #54)

// the sheet
function onOpen(e) { run_('onOpen', [e]); }
function onEdit(e) { if (e && e.range) run_('onEdit', [e]); }
function menuSetUp() { run_('menuSetUp', []); }
function menuFinish() { run_('menuFinish', []); }
function setupFinish() { return run_('setupFinish', []); }   // the Set up dialog's button

// the timers the app sets up (they hand nothing back: a page can call any function in this file). v7.43.2 (#55): each runs
// only for one of this copy's own timers (its id) or for you, signed in; a page with no sign-in can't start them.
function timer_(e) {
  const id = e && e.triggerUid;
  if (id) return ScriptApp.getProjectTriggers().some(t => t.getUniqueId() === String(id));
  try { const me = Session.getEffectiveUser().getEmail(); return !!me && Session.getActiveUser().getEmail() === me; } catch (err) { return false; }
}
function healthCheck(e) { if (timer_(e)) run_('healthCheck', [e]); }
function weeklyBackup(e) { if (timer_(e)) run_('weeklyBackup', [e]); }
function statementScan(e) { if (timer_(e)) run_('statementScan', [e]); }
function warmScreens(e) { if (timer_(e)) run_('warmScreens', [e]); }
